<?php
namespace qqworld_collector\module\artificial_intelligence; if (!defined('ABSPATH')) { exit; } class QQWorld_AI_Context_Manager { private $max_context_tokens; private $system_prompt_tokens = 2000; public function __construct() { $this->max_context_tokens = 0; } public function set_model_context($ctx) { $this->max_context_tokens = absint($ctx); } public function get_available_tokens() { return max(0, $this->max_context_tokens - $this->system_prompt_tokens); } public function estimate_tokens($text) { if (empty($text)) { return 0; } $chinese_chars = preg_match_all('/[\x{4e00}-\x{9fff}]/u', $text); $english_chars = preg_match_all('/[a-zA-Z]/', $text); $other_chars = mb_strlen($text) - $chinese_chars - $english_chars; $tokens = $chinese_chars / 2 + $english_chars / 4 + $other_chars / 4; $tokens += substr_count($text, "\n") * 0.5; return max(1, (int) ceil($tokens)); } public function truncate_messages($messages, $system_prompt = '') { $result = array(); foreach ($messages as $msg) { $item = array( 'role' => $msg['role'], 'content' => $msg['content'], ); if (isset($msg['tool_calls'])) { $item['tool_calls'] = $msg['tool_calls']; } $result[] = $item; } return $result; } private function truncate_text($text, $max_tokens) { $max_chars = $max_tokens * 2; if (mb_strlen($text) <= $max_chars) { return $text; } return mb_substr($text, 0, $max_chars) . '...[已截断]'; } public function prepare_api_messages($messages, $system_prompt = '') { $api_messages = array(); if (!empty($system_prompt)) { $api_messages[] = array( 'role' => 'system', 'content' => $system_prompt, ); } $truncated = $this->truncate_messages($messages, $system_prompt); foreach ($truncated as $msg) { $item = array( 'role' => $msg['role'], 'content' => $msg['content'], ); if (isset($msg['tool_calls'])) { $tool_calls = array(); foreach ($msg['tool_calls'] as $call) { $tool_call = array( 'id' => $call['id'], 'type' => $call['type'], 'function' => array( 'name' => $call['function']['name'], 'arguments' => is_array($call['function']['arguments']) ? json_encode($call['function']['arguments']) : $call['function']['arguments'], ), ); $tool_calls[] = $tool_call; } $item['tool_calls'] = $tool_calls; } $api_messages[] = $item; } return $api_messages; } public function calculate_total_tokens($messages) { $total = 0; foreach ($messages as $msg) { $total += $this->estimate_tokens($msg->content); } return $total; } } 